def solve(coins, amount):
    best = [0] + [None] * amount
    for v in range(1, amount + 1):
        opts = [best[v - c] for c in coins if c <= v and best[v - c] is not None]
        best[v] = min(opts) + 1 if opts else None
    return -1 if best[amount] is None else best[amount]

