def solve(n: int) -> int:
    if n <= 2:
        return 0
    limit = n
    is_prime = bytearray(b'\x01') * limit
    is_prime[0:2] = b'\x00\x00'
    import math
    for i in range(2, int(math.isqrt(limit - 1)) + 1):
        if is_prime[i]:
            step = i
