            # after quoted field, expect comma or end
            if i < n and line[i] == ',':
                i += 1
                continue
            elif i == n:
                break
            else:
                # stray characters
                # treat remaining as part of field until comma
                while i < n and line[i] != ',':
                    field += line[i]
                    i += 1
                fields[-1] = field
