def solve(grid):
    """Count the number of islands in a 2D grid of 0/1 values.
    An island is a group of adjacent 1‑cells connected vertically or horizontally.
    """
    if not grid:
        return 0
    rows = len(grid)
    cols = len(grid[0])
    visited = [[False] * cols for _ in range(rows)]

    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if visited[i][j]:
                continue
            visited[i][j] = True
            # four-directional neighbours
            if i > 0 and grid[i - 1][j] == 1 and not visited[i - 1][j]:
                stack.append((i - 1, j))
            if i + 1 < rows and grid[i + 1][j] == 1 and not visited[i + 1][j]:
                stack.append((i + 1, j))
            if j > 0 and grid[i][j - 1] == 1 and not visited[i][j - 1]:
                stack.append((i, j - 1))
            if j + 1 < cols and grid[i][j + 1] == 1 and not visited[i][j + 1]:
                stack.append((i, j + 1))

    islands = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1 and not visited[i][j]:
                dfs(i, j)
                islands += 1
    return islands

