def solve(coins, amount):
    """Return the fewest number of coins needed to make up *amount* using unlimited
    coins of the given denominations. Return -1 if impossible.
    This uses a bottom‑up DP with O(amount * len(coins)) time.
    """
    # Edge cases
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # Initialize dp array where dp[i] is min coins for amount i
    INF = amount + 1  # larger than any possible number of coins
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for coin in coins:
        if coin <= 0:
            continue  # ignore non‑positive coin values
        for x in range(coin, amount + 1):
            if dp[x - coin] + 1 < dp[x]:
                dp[x] = dp[x - coin] + 1
    return dp[amount] if dp[amount] != INF else -1

