def solve(mat):
    from fractions import Fraction
    n = len(mat)
    if n == 0:
        return 1  # determinant of 0x0 matrix conventionally 1
    # copy as Fraction
    a = [[Fraction(x) for x in row] for row in mat]
    det = Fraction(1)
    for i in range(n):
        # find pivot
        pivot = i
        while pivot < n and a[pivot][i] == 0:
            pivot += 1
        if pivot == n:
            return 0
        if pivot != i:
            a[i], a[pivot] = a[pivot], a[i]
            det *= -1
        det *= a[i][i]
        # eliminate below
        for j in range(i+1, n):
            factor = a[j][i] / a[i][i]
            for k in range(i, n):
                a[j][k] -= factor * a[i][k]
    return int(det)

