            pivot += 1
        if pivot == n:
            return 0
        if pivot != i:
            a[i], a[pivot] = a[pivot], a[i]
            det *= -1
        det *= a[i][i]
        # eliminate rows below
        for j in range(i+1, n):
            factor = a[j][i] / a[i][i]
            for k in range(i, n):
